class Solution:
    def minimumPartitionScore(self, nums: List[int], k: int) -> int:
        n = len(nums)
        P = [0] * (n + 1)
        for i, x in enumerate(nums):
            P[i + 1] = P[i] + x
        v = lambda s: s * (s + 1) // 2
        INF = float('inf')
        dp = [v(P[i]) for i in range(n + 1)]
        dp[0] = 0
        for _ in range(2, k + 1):
            ndp = [INF] * (n + 1)
            for i in range(1, n + 1):
                for m in range(i):
                    if dp[m] < INF:
                        c = dp[m] + v(P[i] - P[m])
                        if c < ndp[i]:
                            ndp[i] = c
            dp = ndp
        return dp[n]

