class Solution {
public:
    long long minimumPartitionScore(vector<int>& nums, int k) {
        int n = nums.size();
        vector<long long> P(n + 1, 0);
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + nums[i];
        auto v = [](long long s) { return s * (s + 1) / 2; };
        const long long INF = LLONG_MAX / 4;
        vector<long long> dp(n + 1);
        for (int i = 0; i <= n; i++) dp[i] = v(P[i]);
        dp[0] = 0;
        for (int j = 2; j <= k; j++) {
            vector<long long> ndp(n + 1, INF);
            for (int i = 1; i <= n; i++)
                for (int m = 0; m < i; m++)
                    if (dp[m] < INF)
                        ndp[i] = min(ndp[i], dp[m] + v(P[i] - P[m]));
            dp = move(ndp);
        }
        return dp[n];
    }
};

