class Solution {
    public long minimumPartitionScore(int[] nums, int k) {
        int n = nums.length;
        long[] P = new long[n + 1];
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + nums[i];
        final long INF = Long.MAX_VALUE / 4;
        long[] dp = new long[n + 1];
        for (int i = 0; i <= n; i++) dp[i] = P[i] * (P[i] + 1) / 2;
        dp[0] = 0;
        for (int j = 2; j <= k; j++) {
            long[] ndp = new long[n + 1];
            Arrays.fill(ndp, INF);
            for (int i = 1; i <= n; i++)
                for (int m = 0; m < i; m++)
                    if (dp[m] < INF)
                        ndp[i] = Math.min(ndp[i], dp[m] + (P[i] - P[m]) * (P[i] - P[m] + 1) / 2);
            dp = ndp;
        }
        return dp[n];
    }
}

