var minimumPartitionScore = function(nums, k) {
    const n = nums.length;
    const P = new Array(n + 1).fill(0n);
    for (let i = 0; i < n; i++) P[i + 1] = P[i] + BigInt(nums[i]);
    const v = s => s * (s + 1n) / 2n;
    const INF = (1n << 100n);
    let dp = Array.from({length: n + 1}, (_, i) => v(P[i]));
    dp[0] = 0n;
    for (let j = 2; j <= k; j++) {
        const ndp = new Array(n + 1).fill(INF);
        for (let i = 1; i <= n; i++)
            for (let m = 0; m < i; m++)
                if (dp[m] < INF)
                    ndp[i] = (ndp[i] < dp[m] + v(P[i] - P[m])) ? ndp[i] : dp[m] + v(P[i] - P[m]);
        dp = ndp;
    }
    return Number(dp[n]);
};

