class Solution {
    vector<long long> P, dp, ndp;
    long long v(long long s) { return s * (s + 1) / 2; }
    void solve(int l, int r, int optL, int optR) {
        if (l > r) return;
        int mid = (l + r) / 2;
        long long best = LLONG_MAX / 4;
        int bo = optL;
        int hi = min(mid - 1, optR);
        for (int m = optL; m <= hi; m++) {
            long long c = dp[m] + v(P[mid] - P[m]);
            if (c < best) { best = c; bo = m; }
        }
        ndp[mid] = best;
        solve(l, mid - 1, optL, bo);
        solve(mid + 1, r, bo, optR);
    }
public:
    long long minimumPartitionScore(vector<int>& nums, int k) {
        int n = nums.size();
        P.assign(n + 1, 0);
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + nums[i];
        dp.assign(n + 1, 0);
        for (int i = 0; i <= n; i++) dp[i] = v(P[i]);
        for (int j = 2; j <= k; j++) {
            ndp.assign(n + 1, LLONG_MAX / 4);
            solve(1, n, 0, n - 1);
            dp.swap(ndp);
        }
        return dp[n];
    }
};

