class Solution {
    private long[] P, dp, ndp;
    private long v(long s) { return s * (s + 1) / 2; }
    private void solve(int l, int r, int optL, int optR) {
        if (l > r) return;
        int mid = (l + r) >>> 1;
        long best = Long.MAX_VALUE / 4;
        int bo = optL;
        int hi = Math.min(mid - 1, optR);
        for (int m = optL; m <= hi; m++) {
            long c = dp[m] + v(P[mid] - P[m]);
            if (c < best) { best = c; bo = m; }
        }
        ndp[mid] = best;
        solve(l, mid - 1, optL, bo);
        solve(mid + 1, r, bo, optR);
    }
    public long minimumPartitionScore(int[] nums, int k) {
        int n = nums.length;
        P = new long[n + 1];
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + nums[i];
        dp = new long[n + 1];
        for (int i = 0; i <= n; i++) dp[i] = v(P[i]);
        for (int j = 2; j <= k; j++) {
            ndp = new long[n + 1];
            Arrays.fill(ndp, Long.MAX_VALUE / 4);
            solve(1, n, 0, n - 1);
            long[] t = dp; dp = ndp; ndp = t;
        }
