var minimumPartitionScore = function(nums, k) {
    const n = nums.length;
    const P = new Array(n + 1).fill(0n);
    for (let i = 0; i < n; i++) P[i + 1] = P[i] + BigInt(nums[i]);
    const v = s => s * (s + 1n) / 2n;
    const INF = (1n << 120n);
    let dp = Array.from({length: n + 1}, (_, i) => v(P[i]));
    let ndp = new Array(n + 1).fill(0n);
    function solve(l, r, optL, optR) {
        if (l > r) return;
        const mid = (l + r) >> 1;
        let best = INF, bo = optL;
        const hi = Math.min(mid - 1, optR);
        for (let m = optL; m <= hi; m++) {
            const c = dp[m] + v(P[mid] - P[m]);
            if (c < best) { best = c; bo = m; }
        }
        ndp[mid] = best;
        solve(l, mid - 1, optL, bo);
        solve(mid + 1, r, bo, optR);
    }
    for (let j = 2; j <= k; j++) {
        ndp.fill(INF);
        solve(1, n, 0, n - 1);
        [dp, ndp] = [ndp, dp];
    }
    return Number(dp[n]);
};
